import { readFileSync } from 'node:fs';
import type { JobRun, TelemetryInput, UserRef } from '../../src/types.js';
import type { DateRange } from '../../src/range.js';
import { seriesGranularity, usageRangeOf } from '../../src/telemetry.js';
import type { UsageInput, UsageReport } from '../../src/usage.js';
import { reduceUsage } from '../../src/usage-reduce.js';
import { rollupsFromFacts, type SessionFieldTotal } from '../../src/usage-rollups.js';

/** What `telemetry-usage.json` holds: the usage facts of one organization plus its run rows. */
export interface FixtureFacts extends UsageInput {
    users: UserRef[];
    fields: SessionFieldTotal[];
}
export interface TelemetryFixture {
    facts: FixtureFacts;
    runs: JobRun[];
}

let cached: TelemetryFixture | null = null;

/**
 * SYNTHETIC. Generated by generate-telemetry.mjs beside it — see that file for the cases it
 * encodes. Regenerate after any change to the facts shape. Fresh copy per call: tests may mutate.
 */
export function sampleFixture(): TelemetryFixture {
    if (!cached) {
        const raw = readFileSync(new URL('./telemetry-usage.json', import.meta.url), 'utf8');
        cached = JSON.parse(raw) as TelemetryFixture;
    }
    const { runs, ...facts } = structuredClone(cached);
    return {
        runs,
        facts: {
            ...(facts as unknown as FixtureFacts),
            foreignSessionIds: new Set((facts as unknown as { foreignSessionIds: string[] }).foreignSessionIds),
        },
    };
}

/** The per-session rollups of the fixture: everything the dashboard aggregates besides tokens. */
export function sampleTelemetry(): TelemetryInput {
    return rollupsFromFacts(sampleFixture().facts);
}

export const FIXTURE_REPO = 'Bellows-AI/bellows.ai';

/** The window the fixture was generated in, so `partial` week flags stay stable. */
export const FIXTURE_NOW = new Date('2026-08-21T12:00:00.000Z');

export interface ReportScope {
    repos?: readonly string[];
    userId?: string;
    range?: DateRange;
    now?: Date;
}

/** The usage report of the fixture facts under one scope — what the server reduces at read time. */
export function fixtureReport({ repos, userId, range, now = FIXTURE_NOW }: ReportScope = {}): UsageReport {
    const { facts } = sampleFixture();
    const input = rollupsFromFacts(facts);
    return reduceUsage(facts, {
        range: range ? usageRangeOf(range) : null,
        now,
        granularity: seriesGranularity(range, input, now),
        ...(repos ? { repos } : {}),
        ...(userId ? { userId } : {}),
    });
}

/** A report over no facts at all: for stats tests that only look at session figures. */
export const EMPTY_REPORT: UsageReport = reduceUsage(
    { orgId: 'empty', board: [], branch: [], foreignSessionIds: new Set(), contributions: [], spans: [] },
    { range: null, now: FIXTURE_NOW }
);

/** Sum of one token type over the fixture's timed points of the given sessions, recomputed from the raw points. */
export function fixturePointSum(sessionIds: readonly string[], type: keyof UsageReport['eligible']['tokens']): number {
    return sampleFixture()
        .facts.contributions.filter((c) => c.kind === 'timed' && sessionIds.includes(c.selection.sessionId as string))
        .reduce((sum, c) => sum + (c.tokens[type] ?? 0), 0);
}
